#!/bin/bash -eu
# Generated by fuzzbench_generate.py for bug transplant evaluation

cd /src/ghostpdl

# Drop stale build artifacts from the merge container so `git checkout`
# is not blocked by untracked files that would be overwritten.
git clean -fdx >/dev/null 2>&1 || true
git reset --hard HEAD >/dev/null 2>&1 || true

# Checkout target commit
git checkout 4c4dcc85ce4f3c7fe53f72dd0098cd7906312dbd

# Restore harness sources that live outside the project git repository,
# and compute --exclude flags so harness.diff doesn't re-modify files
# that have already been restored to their post-dispatch state by the
# snapshot copy (which would fail with "does not match index").
HARNESS_EXCLUDES=""
if [ -f /src/patches/harness_sources/manifest.json ]; then
    HARNESS_EXCLUDES=$(python3 - <<'PY'
import json
import shutil
from pathlib import Path

root = Path("/src/patches/harness_sources")
manifest = json.loads((root / "manifest.json").read_text())
excludes = []
for entry in manifest:
    source = root / entry["snapshot"]
    destination = Path(entry["container_path"])
    destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(source, destination)
    # Convert /src/<repo>/<rel> to <rel> (git apply paths are repo-relative).
    parts = destination.parts
    if len(parts) >= 3 and parts[1] == "src":
        rel = Path(*parts[3:])
    else:
        rel = destination
    excludes.append(f"--exclude={rel}")
print(" ".join(excludes))
PY
)
fi

# Apply dispatch harness first (modifies build system), then bug patches.
# $HARNESS_EXCLUDES is empty when no snapshots were restored.
if ! git apply --check $HARNESS_EXCLUDES /src/patches/harness.diff 2>/dev/null; then
    echo "Trying git apply --3way for harness.diff..."
    git apply --3way $HARNESS_EXCLUDES /src/patches/harness.diff
else
    git apply $HARNESS_EXCLUDES /src/patches/harness.diff
fi

# $HARNESS_EXCLUDES applies here too: the harness file is restored whole
# from harness_sources/, so combined.diff's hunks for it would collide
# ("does not match index"). Since the snapshot is taken after the merge it
# already carries every per-bug harness gate.
if ! git apply --check $HARNESS_EXCLUDES /src/patches/combined.diff 2>/dev/null; then
    echo "Trying git apply --3way for combined.diff..."
    git apply --3way $HARNESS_EXCLUDES /src/patches/combined.diff
else
    git apply $HARNESS_EXCLUDES /src/patches/combined.diff
fi

# --- Fix library CMakeLists.txt for new source files from combined.diff ---
# combined.diff may create new .c files (e.g., zfp_getcell.c) that need to
# be added to the library's explicit source list.
if [ -d blosc ] && [ -f blosc/CMakeLists.txt ]; then
    for newfile in blosc/*.c; do
        base=$(basename "$newfile")
        if ! grep -q "$base" blosc/CMakeLists.txt 2>/dev/null; then
            echo "Adding $base to blosc/CMakeLists.txt"
            sed -i "/^set(SOURCES /s/)/ $base)/" blosc/CMakeLists.txt
        fi
    done
fi

# --- Sanitizers: ASan only ---
# These benchmarks are built with SANITIZER=address and their oracle counts
# ASan reports and aborts. Any UBSan instrumentation that leaks in through the
# environment produces recoverable "runtime error:" noise in every crash log,
# and under aflplusplus (ASAN_OPTIONS=abort_on_error=1) turns it into a
# SIGABRT that kills seeds during calibration. Drop it from the inherited
# flags; -fsanitize=address and libFuzzer's own flags are kept.
for _var in CFLAGS CXXFLAGS; do
    eval "_val=\${$_var:-}"
    _val=$(printf '%s' "$_val" | sed -E         -e 's/-fsanitize=undefined[^ ]*//g'         -e 's/-fsanitize=(array-bounds|bool|builtin|enum|float-divide-by-zero|function|integer|integer-divide-by-zero|null|object-size|return|returns-nonnull-attribute|shift|signed-integer-overflow|unreachable|vla-bound|vptr)[^ ]*//g'         -e 's/-f(no-)?sanitize-(recover|trap)=[^ ]*//g'         -e 's/  +/ /g')
    eval "export $_var=\"\$_val\""
done

# --- Original build commands ---
export CFLAGS="${CFLAGS:-} -Wno-error=implicit-function-declaration"
export CXXFLAGS="${CXXFLAGS:-} -Wno-error=implicit-function-declaration"

pushd $SRC/cups
# Fix bad line
sed -i '2110s/\(\s\)f->value/\1(int)f->value/' cups/ppd-cache.c

LSB_BUILD=y ./configure --prefix="$WORK" --libdir="$OUT" --disable-gnutls \
   --disable-libusb --with-components=core

make clean
make install-headers install-libs
make -C filter libs install-libs
install -m755 cups-config "$WORK"/cups-config
popd


if [ ! -d freetype ] && [ -d "$SRC/freetype" ]; then cp -a "$SRC/freetype" freetype; fi

CUPSCONFIG="$WORK/cups-config"
CUPS_CFLAGS=$($CUPSCONFIG --cflags)
CUPS_LDFLAGS=$($CUPSCONFIG --ldflags)
CUPS_LIBS=$($CUPSCONFIG --image --libs)
export CXXFLAGS="$CXXFLAGS $CUPS_CFLAGS"

# --disable-fontconfig below: fontconfig only enumerates SYSTEM fonts, which
# a fuzzed PDF never uses -- the grafted bugs are in embedded-font parsing
# (gstype2.c, ttinterp.c). When the headers happen to be present configure
# enables it and compiles gp_unix.c against it, but nothing puts -lfontconfig
# on the link line (pkg-config has no fontconfig in these images), so the link
# dies on undefined FcPatternGetString / FcConfigDestroy. Whether the headers
# were present varied per fuzzer image, so the six fuzzers were not even
# building the same ghostscript. Disabling it makes them identical.
CPPFLAGS="${CPPFLAGS:-} $CUPS_CFLAGS -DPACIFY_VALGRIND" ./autogen.sh \
  CUPSCONFIG=$CUPSCONFIG \
  --enable-freetype --disable-fontconfig \
  --enable-cups --with-ijs --with-jbig2dec \
  --with-drivers=pdfwrite,cups,ljet4,laserjet,pxlmono,pxlcolor,pcl3,uniprint,pgmraw,ps2write,png16m,tiffsep1,faxg3,psdcmyk,eps2write,bmpmono,xpswrite --without-x
# (generator) ASan-only: drop every UBSan flag autogen.sh injected.
# Matching one literal check list is too fragile -- autogen writes the
# checks out in whatever order it detected them -- so rewrite each
# -fsanitize= list and keep only address/fuzzer components.
python3 - <<'STRIP_UBSAN'
import os, re
KEEP = ("address", "fuzzer", "fuzzer-no-link")
def fix_list(match):
    kept = [c for c in match.group(1).split(",") if c in KEEP]
    return "-fsanitize=" + ",".join(kept) if kept else ""
changed = 0
for root, _, files in os.walk("."):
    for name in files:
        if name != "Makefile" and not name.endswith(".mak"):
            continue
        path = os.path.join(root, name)
        try:
            text = open(path, encoding="utf-8", errors="replace").read()
        except OSError:
            continue
        new = re.sub(r"-fsanitize=([\w,-]+)", fix_list, text)
        new = re.sub(r"-f(no-)?sanitize-(recover|trap)=[^\s]*", "", new)
        new = new.replace("-fsanitize-undefined-trap-on-error", "")
        if new != text:
            open(path, "w", encoding="utf-8").write(new)
            changed += 1
print("stripped UBSan flags from %d makefile(s)" % changed)
STRIP_UBSAN
make -j$(nproc) libgs

# Compile __bug_dispatch.c for the fuzzers
$CC $CFLAGS -c $SRC/ghostpdl/__bug_dispatch.c -o $WORK/__bug_dispatch.o

fuzzers="gstoraster_fuzzer                \
         gstoraster_fuzzer_all_colors     \
         gstoraster_ps_fuzzer             \
         gstoraster_pdf_fuzzer            \
         gs_device_pdfwrite_fuzzer        \
         gs_device_pxlmono_fuzzer         \
         gs_device_pgmraw_fuzzer          \
         gs_device_ps2write_fuzzer        \
         gs_device_png16m_fuzzer          \
         gs_device_psdcmyk_fuzzer         \
         gs_device_eps2write_fuzzer       \
         gs_device_faxg3_fuzzer           \
         gs_device_bmpmono_fuzzer         \
         gs_device_xpswrite_fuzzer        \
         gs_device_pxlcolor_fuzzer        \
         gs_device_tiffsep1_fuzzer        \
         gs_device_pdfwrite_opts_fuzzer"

for fuzzer in $fuzzers; do
  $CXX $CXXFLAGS $CUPS_LDFLAGS -std=c++11 -I. -I$SRC \
    $SRC/${fuzzer}.cc \
    -o "$OUT/${fuzzer}" \
    -Wl,-rpath='$ORIGIN' \
    $CUPS_LIBS \
    $LIB_FUZZING_ENGINE bin/gs.a $WORK/__bug_dispatch.o
done

# Create PDF seed corpus
zip -j "$OUT/gstoraster_pdf_fuzzer_seed_corpus.zip" $SRC/pdf_seeds/*

# Create corpus for gstoraster_fuzzer_all_colors. Only use seeds of a few KB in size.
mkdir -p "$WORK/all_color_seeds"
for f in examples/ridt91.eps examples/snowflak.ps $SRC/pdf_seeds/pdf.pdf; do
  # Prepend a single byte to seed, because it's used to determine the color
  # scheme in the gstoraster_fuzzer_all_colors.
  printf "\x01" | cat - "$f" > tmp_file.txt
  mv tmp_file.txt $f
  s=$(sha1sum "$f" | awk '{print $1}')
  cp "$f" "$WORK/all_color_seeds/$s"
done
zip -j "$OUT/gstoraster_fuzzer_all_colors_seed_corpus.zip" "$WORK"/all_color_seeds/*

# Do the same thing with pdfwrites opt fuzzer, but multiple bytes
mkdir -p "$WORK/gs_device_pdfwrite_opts_fuzzer_seeds"
for f in examples/ridt91.eps examples/snowflak.ps $SRC/pdf_seeds/pdf.pdf; do
  # Prepend the number of bytes used for picking options in the opts fuzzer
  printf "\x01\x01" | cat - "$f" > tmp_file.txt
  mv tmp_file.txt $f
  s=$(sha1sum "$f" | awk '{print $1}')
  cp "$f" "$WORK/gs_device_pdfwrite_opts_fuzzer_seeds/$s"
done
zip -j "$OUT/gs_device_pdfwrite_opts_fuzzer_seed_corpus.zip" "$WORK"/gs_device_pdfwrite_opts_fuzzer_seeds/*

# Create seeds for gstoraster_fuzzer
mkdir -p "$WORK/seeds"
for f in examples/*.{ps,pdf}; do
  s=$(sha1sum "$f" | awk '{print $1}')
  cp "$f" "$WORK/seeds/$s"
done

# Create corpus for gstoraster_fuzzer
zip -j "$OUT/gstoraster_fuzzer_seed_corpus.zip" "$WORK"/seeds/*
cp "$OUT/gstoraster_fuzzer_seed_corpus.zip" "$OUT/gs_device_pdfwrite_fuzzer_seed_corpus.zip"
cp "$OUT/gstoraster_fuzzer_seed_corpus.zip" "$OUT/gs_device_pxlmono_fuzzer_seed_corpus.zip"
cp "$OUT/gstoraster_fuzzer_seed_corpus.zip" "$OUT/gs_device_eps2write_fuzzer_seed_corpus.zip"
cp "$OUT/gstoraster_fuzzer_seed_corpus.zip" "$OUT/gs_device_bmpmono_fuzzer_seed_corpus.zip"
cp "$OUT/gstoraster_fuzzer_seed_corpus.zip" "$OUT/gs_device_xpswrite_fuzzer_seed_corpus.zip"
cp "$OUT/gstoraster_fuzzer_seed_corpus.zip" "$OUT/gs_device_pxlcolor_fuzzer_seed_corpus.zip"

# Copy out options
cp $SRC/*.options $OUT/

# Copy out dictionary
fuzzers_with_dict="gstoraster_fuzzer  \
         gstoraster_fuzzer_all_colors \
         gstoraster_pdf_fuzzer        \
         gs_device_pdfwrite_fuzzer    \
         gs_device_faxg3_fuzzer       \
         gs_device_bmpmono_fuzzer     \
         gs_device_xpswrite_fuzzer"

for fuzzer in $fuzzers_with_dict; do
  cp $SRC/dicts/pdf.dict $OUT/${fuzzer}.dict
done
cp $SRC/dicts/ps.dict $OUT/gstoraster_ps_fuzzer.dict

# --- Seed corpus: expand original seeds and per-bug testcase candidates ---
# FuzzBench uses $OUT/{fuzz_target}_seed_corpus.zip as initial corpus.
# Create one seed variant for the default path plus one for each dispatch bit.
# Per-bug reproducers are used only as source material: exact crashing inputs
# are filtered out before packaging.
seed_zip="$OUT/gs_device_pdfwrite_fuzzer_seed_corpus.zip"
seed_target="$OUT/gs_device_pdfwrite_fuzzer"
mkdir -p /tmp/seeds_dispatch /tmp/original_seeds

if [ -f "$seed_zip" ]; then
    unzip -q -o "$seed_zip" -d /tmp/original_seeds 2>/dev/null || true
    for f in /tmp/original_seeds/*; do
        [ -f "$f" ] || continue
        base=$(basename "$f")
        # Dispatch-zero ONLY. Expanding the project corpus across every slot
        # would hand the fuzzer inputs that already open a bug's gate, so the
        # selector byte would not have to be discovered. Slot 0 = no bug.
        printf '\000' | cat - "$f" > "/tmp/seeds_dispatch/${base}.dispatch_00"
    done
fi

# Initial corpus: the project's public ClusterFuzz corpus, already
# dispatch-zero prefixed (head byte 0x00 = slot 0 = no bug) and
# crash-filtered against this benchmark. Fuzzers must mutate the selector
# byte themselves to reach any gated bug, so no seed opens a bug's gate.
#
# Per-bug PoC derivatives are deliberately NOT used as seeds: truncations of
# a reproducer hand the fuzzer most of the structure needed to rebuild it,
# which flatters time-to-bug.
for _z in /src/corpus_seeds*.zip; do
    [ -f "$_z" ] || continue
    echo "Unpacking initial corpus: $_z"
    unzip -q -o "$_z" -d /tmp/seeds_dispatch
done

# NOTE: do not use `ls /tmp/seeds_dispatch/*` here. With a large corpus the
# glob exceeds ARG_MAX, the test silently fails, the seed zip is never
# written, and FuzzBench starts the fuzzers from a fake 2-byte seed.
if [ -n "$(find /tmp/seeds_dispatch -maxdepth 1 -type f -print -quit 2>/dev/null)" ]; then
    rm -f "$seed_zip"
    find /tmp/seeds_dispatch -maxdepth 1 -type f -print0 | xargs -0 zip -j -q "$seed_zip"
fi
